  Lemma fwin_o_disjoint : forall LF k ff fp W A n, fresh_frame H LF k ff fp -> Forall (fwin_o LF k ff) W ->
    A + n <= AIMG_TOP -> (A + n <= AERRNO \/ AERRNO + 4 <= A) -> disjoint_from W A n.
  Proof.
    intros LF k ff fp W A n FF FW HA HE. induction W as [|iv W IH]; [exact I|].
    destruct iv as [l h]. cbn. split; [exact (fwin_o_off _ _ _ _ (l, h) A n FF (Forall_inv FW) HA HE)| apply IH; exact (Forall_inv_tail FW)].
  Qed.

  Lemma AXStatics2_fwin : forall LF k ff fp m m' W,
    AXStatics2 m -> munch W m m' -> wmono asegs m m' -> fresh_frame H LF k ff fp -> Forall (fwin_o LF k ff) W -> AXStatics2 m'.
  Proof.
    intros LF k ff fp m m' W XS MU WM FF FW. eapply AXStatics2_transport; [exact XS| exact MU| exact WM|].
    eapply Forall_impl; [| exact FW]. intros [l h] K.
    destruct (fwin_o_off _ _ _ _ (l, h) 0x115000 (0x125e40 - 0x115000) FF K ltac:(unfold AIMG_TOP; lia) ltac:(left; rewrite AERRNO_val; lia)) as [E|E];
      cbn [fst snd] in *; [left| right]; lia.
  Qed.

  Lemma ACanaryReads_fwin : forall LF k ff fp m m' W,
    ACanaryReads m -> munch W m m' -> fresh_frame H LF k ff fp -> Forall (fwin_o LF k ff) W -> ACanaryReads m'.
  Proof.
    intros LF k ff fp m m' W CR MU FF FW.
    eapply ACanaryReads_transport; [exact CR| exact MU| |]; eapply fwin_o_disjoint; try exact FF; try exact FW;
      unfold AG_GOT_STACK_CHK, AG_STACK_CHK_GUARD, AIMG_TOP; rewrite ?AERRNO_val; lia.
  Qed.

End HCW.
